function solve(a,b){const c=e(a);let d=null;for(const x of b){if(d!==null&&x.length>=d.length){continue;}const a=h(x);let r=true;for(let i=0;i<26;i+=1){if(a[i]<c[i]){r=false;break;}}if(r){d=x;}}return d;}function h(a){const b=new Array(26).fill(0);for(const x of a){const a=x.charCodeAt(0)-97;b[a]+=1;}return b;}function e(a){const b=new Array(26).fill(0);for(const x of a){let a=x.charCodeAt(0)-65;if(a>=0&&a<26){b[a]+=1;}else{a=x.charCodeAt(0)-97;if(a>=0&&a<26){b[a]+=1;}}}return b;}
